package com.ias.ticket;

import com.ias.trust.*;
import jakarta.servlet.http.HttpServletRequest;
import org.springframework.stereotype.Component;
import org.springframework.scheduling.annotation.Scheduled;
import org.springframework.beans.factory.annotation.Autowired;
import java.time.*;
import java.sql.Timestamp;
import java.util.*;
import java.security.MessageDigest;
import java.nio.charset.StandardCharsets;

/** Durable W queue. Network calls never hold W business locks. No timeout is a terminal fact. */
@Component
public final class FinanceFreezeCoordinator {
    static final List<String> OWNERS=List.of("approval","stock");
    static final Set<String> WIRE=Set.of("tenantId","actorUserId","companyId","faultRelationId","ticketId","roundId","groupId","expectedGroupVersion","quoteId","operationId","commandDigest","freezeId","generation","ticketFenceDigest");
    record Context(String trace,long deadline){}
    @FunctionalInterface interface Sources {FinanceQuoteBoundary.SourceFact read(FinanceQuoteBoundary.Binding b,Context c);}
    @FunctionalInterface interface Owners {Map<String,Object> call(String owner,String action,Map<String,Object> binding,Context c);}
    final Tickets t;final Sources sources;final Owners owners;
    @Autowired public FinanceFreezeCoordinator(Tickets t){this(t,(b,c)->FinanceQuoteSourceAdapter.parse(b,Chain.call("ticket-finance","/internal/finance/quote-sources/query",FinanceQuoteSourceAdapter.request(b),c.trace(),c.deadline()),c.deadline()),(owner,action,b,c)->Chain.call("ticket-"+owner,"/internal/"+owner+"/finance-fences/"+action,b,c.trace(),c.deadline()));}
    FinanceFreezeCoordinator(Tickets t,Sources sources,Owners owners){this.t=t;this.sources=sources;this.owners=owners;}
    static Context context(HttpServletRequest r){return new Context(Chain.trace(r),Chain.deadline(r));}
    static Timestamp now(){return Timestamp.from(Instant.now().truncatedTo(java.time.temporal.ChronoUnit.MILLIS));}
    static String sha(Object o){try{return HexFormat.of().formatHex(MessageDigest.getInstance("SHA-256").digest(Chain.JSON.writeValueAsBytes(o)));}catch(Exception e){throw new IllegalStateException(e);}}
    static String str(Map<String,Object> m,String field){Object o=m.get(field);if(!(o instanceof String s)||s.isBlank())throw Tickets.bad();return s;}
    Map<String,Object> fence(String id){var rows=t.db.queryForList("SELECT * FROM ticket_finance_quote_fence WHERE freeze_id=?",id);if(rows.isEmpty())throw new Problem(404,"OPERATION_NOT_FOUND");return rows.getFirst();}
    Map<String,Object> coordination(String id){var rows=t.db.queryForList("SELECT * FROM ticket_finance_coordination WHERE freeze_id=?",id);if(rows.isEmpty())throw new Problem(503,"FINANCE_COORDINATION_MISSING");return rows.getFirst();}
    static Map<String,Object> wire(Map<String,Object> f){var b=FinanceQuoteBoundary.binding(f);var out=new TreeMap<>(FinanceQuoteSourceAdapter.request(b));out.put("freezeId",f.get("freeze_id").toString());out.put("generation",f.get("generation").toString());out.put("ticketFenceDigest",sha(out));return Collections.unmodifiableMap(out);}
    void requireWire(Map<String,Object> input,Map<String,Object> row){if(!input.keySet().equals(WIRE))throw Tickets.bad();for(var field:wire(row).entrySet())if(!field.getValue().equals(input.get(field.getKey())))throw new Problem(409,"FINANCE_FREEZE_BINDING_MISMATCH");}
    FinanceQuoteBoundary.SourceFact source(Map<String,Object> row,Context context){var b=FinanceQuoteBoundary.binding(row);var fact=sources.read(b,context);if(fact==null||!fact.binding().equals(b)||!Set.of("IN_PROGRESS","COMMITTED","ABORTED").contains(fact.state())||("COMMITTED".equals(fact.state())?fact.resultDigest()==null||!fact.resultDigest().matches("[0-9a-f]{64}"):fact.resultDigest()!=null))throw new Problem(503,"FINANCE_SOURCE_STATE_NOT_CONFIRMED");return fact;}
    Map<String,Object> proof(Map<String,Object> body,Context c){var row=fence(Tickets.uuid(body.get("freezeId")));requireWire(body,row);var source=source(row,c);var out=new LinkedHashMap<>(wire(row));out.put("sourceState",source.state());out.put("resultDigest",source.resultDigest());out.put("coordinationState",coordination(row.get("freeze_id").toString()).get("state"));
        var permits=t.db.queryForList("SELECT p.operation_id,p.actor_user_id,p.approval_id,p.phase,p.command_digest,r.operation_id AS completed FROM ticket_stock_execution p LEFT JOIN ticket_stock_execution_result r ON r.operation_id=p.operation_id WHERE p.tenant_id=? AND p.ticket_id=? ORDER BY p.operation_id LIMIT 1001",row.get("tenant_id"),row.get("ticket_id"));if(permits.size()>1000)throw new Problem(503,"FINANCE_SCOPE_SNAPSHOT_LIMIT");
        out.put("scopedOperationIds",permits.stream().map(p->p.get("operation_id").toString()).toList());out.put("inFlightOperationIds",permits.stream().filter(p->p.get("completed")==null).map(p->p.get("operation_id").toString()).toList());
        out.put("inFlightPermits",permits.stream().filter(p->p.get("completed")==null).map(p->Map.of("operationId",p.get("operation_id").toString(),"actorUserId",p.get("actor_user_id").toString(),"orderId",p.get("approval_id").toString(),"phase",p.get("phase").toString(),"commandDigest",p.get("command_digest").toString())).toList());out.put("checkedAt",Instant.now().toString());return out;
    }
    void audit(String freeze,String event,String state,String digest){var old=t.db.queryForList("SELECT source_state,result_digest FROM ticket_finance_coordination_audit WHERE freeze_id=? AND event_name=?",freeze,event);if(!old.isEmpty()){if(!Objects.equals(state,old.getFirst().get("source_state"))||!Objects.equals(digest,old.getFirst().get("result_digest")))throw new Problem(409,"FINANCE_TERMINAL_CONFLICT");return;}t.db.update("INSERT INTO ticket_finance_coordination_audit VALUES(?,?,?,?,?)",freeze,event,state,digest,now());}
    <T> T locked(Map<String,Object> f,java.util.function.Supplier<T> work){return t.tx.execute(tx->{t.db.queryForMap("SELECT id FROM ticket_record WHERE id=? AND tenant_id=? FOR UPDATE",f.get("ticket_id"),f.get("tenant_id"));return work.get();});}
    void ownerAck(Map<String,Object> f,String owner,String phase,Map<String,Object> receipt,FinanceQuoteBoundary.SourceFact source,Context c){
        Chain.fresh(receipt,c.deadline());for(var field:wire(f).entrySet())if(!field.getValue().equals(receipt.get(field.getKey())))throw new Problem(503,"FINANCE_OWNER_BINDING_MISMATCH");
        String expected=phase.equals("FENCED")?"OWNER_FENCED":"OWNER_RELEASED";if(!owner.equals(receipt.get("owner"))||!expected.equals(receipt.get("state"))||!(receipt.get("ackDigest") instanceof String digest)||!digest.matches("[0-9a-f]{64}"))throw new Problem(503,"FINANCE_OWNER_ACK_NOT_CONFIRMED");
        if(phase.equals("RELEASED")&&(!source.state().equals(receipt.get("sourceState"))||!Objects.equals(source.resultDigest(),receipt.get("resultDigest"))))throw new Problem(503,"FINANCE_OWNER_TERMINAL_MISMATCH");
        if(phase.equals("FENCED")&&(!(receipt.get("coverageDigest") instanceof String coverage)||!coverage.matches("[0-9a-f]{64}")||receipt.get("localSnapshot")==null))throw new Problem(503,"FINANCE_OWNER_COVERAGE_MISSING");
        locked(f,()->{var old=t.db.queryForList("SELECT ack_digest FROM ticket_finance_owner_ack WHERE freeze_id=? AND owner_name=? AND phase=?",f.get("freeze_id"),owner,phase);if(!old.isEmpty()){if(!digest.equals(old.getFirst().get("ack_digest")))throw new Problem(409,"FINANCE_OWNER_ACK_CONFLICT");return null;}t.db.update("INSERT INTO ticket_finance_owner_ack VALUES(?,?,?,?,?,?)",f.get("freeze_id"),owner,phase,digest,Chain.JSON.writeValueAsString(receipt),now());return null;});
    }
    boolean hasAck(String freeze,String owner,String phase){return t.db.queryForObject("SELECT COUNT(*) FROM ticket_finance_owner_ack WHERE freeze_id=? AND owner_name=? AND phase=?",Long.class,freeze,owner,phase)==1;}
    void setState(Map<String,Object> f,String state,FinanceQuoteBoundary.SourceFact source){locked(f,()->{if(state.equals("FROZEN")||state.equals("RELEASED"))FeePartPermitBarrier.guard(t,f.get("ticket_id"));var old=coordination(f.get("freeze_id").toString());String previous=old.get("state").toString();if(previous.equals("RELEASED")&&!state.equals("RELEASED")||previous.equals("RECONCILING")&&state.equals("FROZEN"))throw new Problem(409,"FINANCE_COORDINATION_STATE_CONFLICT");if(old.get("source_state")!=null&&!old.get("source_state").equals("IN_PROGRESS")&&(!old.get("source_state").equals(source.state())||!Objects.equals(old.get("result_digest"),source.resultDigest())))throw new Problem(409,"FINANCE_TERMINAL_CONFLICT");if(state.equals("RECONCILING")&&source.state().equals("COMMITTED")){var result=t.db.queryForList("SELECT result_digest FROM ticket_finance_quote_source_result WHERE freeze_id=?",f.get("freeze_id"));if(result.isEmpty())t.db.update("INSERT INTO ticket_finance_quote_source_result VALUES(?,?,?)",f.get("freeze_id"),source.resultDigest(),now());else if(!source.resultDigest().equals(result.getFirst().get("result_digest")))throw new Problem(409,"FINANCE_SOURCE_RESULT_MISMATCH");}t.db.update("UPDATE ticket_finance_coordination SET state=?,source_state=?,result_digest=?,row_version=row_version+1,updated_at=? WHERE freeze_id=?",state,source.state(),source.resultDigest(),now(),f.get("freeze_id"));audit(f.get("freeze_id").toString(),state,source.state(),source.resultDigest());return null;});}
    Map<String,Object> advance(String freeze,Context c){var f=fence(freeze);String lease=UUID.randomUUID().toString();Timestamp time=now();int claim=t.db.update("UPDATE ticket_finance_coordination SET lease_id=?,lease_until=?,attempts=attempts+1 WHERE freeze_id=? AND state<>'RELEASED' AND (lease_until IS NULL OR lease_until<?)",lease,Timestamp.from(Instant.now().plusSeconds(30)),freeze,time);if(claim==0)return view(f);
        String error=null;
        try{var fact=source(f,c);boolean terminal=!fact.state().equals("IN_PROGRESS");String phase=terminal?"RELEASED":"FENCED";
            if(terminal)setState(f,"RECONCILING",fact);
            for(String owner:OWNERS){if(hasAck(freeze,owner,phase))continue;var receipt=owners.call(owner,terminal?"reconcile":"prepare",wire(f),c);if("WAITING_OWNER_OPERATIONS".equals(receipt.get("state")))throw new Problem(503,"FINANCE_OWNER_OPERATIONS_PENDING");ownerAck(f,owner,phase,receipt,fact,c);}
            var current=source(f,c);if(!fact.equals(current))throw new Problem(503,"FINANCE_SOURCE_CHANGED_RETRY");
            if(!terminal&&t.db.queryForObject("SELECT COUNT(*) FROM ticket_stock_execution p LEFT JOIN ticket_stock_execution_result r ON r.operation_id=p.operation_id WHERE p.ticket_id=? AND r.operation_id IS NULL",Long.class,f.get("ticket_id"))>0)throw new Problem(503,"FINANCE_OWNER_OPERATIONS_PENDING");
            setState(f,terminal?"RELEASED":"FROZEN",fact);return view(f);
        }catch(Problem failure){error=failure.code;throw failure;}catch(RuntimeException failure){error="DEPENDENCY_UNAVAILABLE";throw failure;}finally{t.db.update("UPDATE ticket_finance_coordination SET lease_id=NULL,lease_until=NULL,next_attempt_at=?,last_error_code=?,updated_at=? WHERE freeze_id=? AND lease_id=?",Timestamp.from(Instant.now().plusSeconds(error==null?5:2)),error,now(),freeze,lease);}
    }
    Map<String,Object> view(Map<String,Object> f){var out=new LinkedHashMap<>(FinanceQuoteBoundary.view(f));out.putAll(wire(f));var co=coordination(f.get("freeze_id").toString());String state=co.get("state").toString();boolean frozen=state.equals("FROZEN")&&OWNERS.stream().allMatch(o->hasAck(f.get("freeze_id").toString(),o,"FENCED"));out.put("coordinationState",state);out.put("quoteWritable",frozen);out.put("executionBarrierClear",frozen);out.put("globalFreezeAck",frozen);out.put("sourceState",co.get("source_state"));out.put("resultDigest",co.get("result_digest"));out.put("requiredOwners",OWNERS);out.put("checkedAt",Instant.now().toString());return out;}
    @Scheduled(fixedDelay=2000,initialDelay=5000) public void tick(){if(!Chain.active()||!"ticket".equals(Chain.role()))return;try{for(var row:t.db.queryForList("SELECT freeze_id FROM ticket_finance_coordination WHERE state<>'RELEASED' AND next_attempt_at<=? AND (lease_until IS NULL OR lease_until<?) ORDER BY next_attempt_at LIMIT 8",now(),now())){String freeze=row.get("freeze_id").toString();try{advance(freeze,new Context(UUID.randomUUID().toString(),System.currentTimeMillis()+10000));}catch(RuntimeException ignored){/* persisted retry metadata, no secrets or fake terminal */}}}catch(RuntimeException ignored){/* schema/DB unavailable: no release */}}
}
